def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_op = history[-1]

    opp_d = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1

    if opp_d == n:
        return 'D'

    rate = opp_d / float(n)

    start = n - 10
    if start < 0:
        start = 0
    recent_od = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_od += 1

    streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak += 1
        else:
            break

    if recent_od >= 7 or rate > 0.6 or streak >= 5:
        return 'D'

    if opp_d == 0:
        if n >= 98:
            return 'D'
        return 'C'

    if last_op == 'D':
        prev_me = history[-2][0] if n >= 2 else 'C'

        if last_me == 'D':
            if streak >= 3:
                return 'D'
            if rng.random() < 0.82:
                return 'C'
            return 'D'

        if prev_me == 'D':
            if streak >= 3:
                return 'D'
            if rng.random() < 0.75:
                return 'C'
            return 'D'

        if rate < 0.2 and recent_od == 0 and streak == 1:
            if rng.random() < 0.25:
                return 'C'
        return 'D'

    if last_me == 'D':
        if recent_od == 0 and rate < 0.2:
            if n >= 88:
                if rng.random() < 0.55:
                    return 'D'
            else:
                if rng.random() < 0.12:
                    return 'D'
        return 'C'

    if rate < 0.35 and n >= 98:
        return 'D'

    if rate < 0.15 and n >= 90 and rng.random() < 0.07:
        return 'D'

    return 'C'
